#include <iostream>
using namespace std;

int main() {
    long long n, prod = 1;
    cin >> n;

    do {
        int digit = n % 10;

        if (digit == 8 || digit == 0)
            prod *= 2;
        else if (digit == 7 || digit == 1)
            prod *= 5;
        else if (digit == 3)
            prod *= 3;

        n /= 10;
    } while (n > 0);

    cout << prod << '\n';
    return 0;
}

